        "code": "import { SettingsIcon } from \"lucide-react\"\n\nimport { Button } from \"@/components/ui/button\"\nimport { PageBreadcrumbs } from \"@/components/openlmis/page-breadcrumbs\"\n\nimport {\n  Workspace,\n  WorkspaceActions,\n  WorkspaceContent,\n  WorkspaceDescription,\n  WorkspaceFooter,\n  WorkspaceHeader,\n  WorkspaceHeading,\n  WorkspaceIcon,\n  WorkspaceTitle,\n} from \"@/components/blocks/openlmis/workspace\"\n\nexport default function Page() {\n  return (\n    <>\n      <Workspace width=\"narrow\">\n        <PageBreadcrumbs\n          items={[\n            { label: \"Home\", href: \"#\" },\n            { label: \"Settings\" },\n            { label: \"General\" },\n          ]}\n        />\n        <WorkspaceHeader>\n          <WorkspaceHeading>\n            <WorkspaceIcon>\n              <SettingsIcon />\n            </WorkspaceIcon>\n            <WorkspaceTitle>General Settings</WorkspaceTitle>\n            <WorkspaceDescription>\n              A narrow page, for settings that read as one short column.\n            </WorkspaceDescription>\n          </WorkspaceHeading>\n          <WorkspaceActions>\n            <Button size=\"lg\" variant=\"outline\">\n              Reset\n            </Button>\n          </WorkspaceActions>\n        </WorkspaceHeader>\n        <WorkspaceContent>\n          <div className=\"flex h-40 items-center justify-center rounded-xl border border-dashed text-sm text-muted-foreground\">\n            Page content\n          </div>\n        </WorkspaceContent>\n      </Workspace>\n      <WorkspaceFooter width=\"narrow\">\n        <Button variant=\"outline\">Cancel</Button>\n        <Button>Save</Button>\n      </WorkspaceFooter>\n    </>\n  )\n}",
